235	        // 同键同参：重放原结果，不产生新版本
236	        ApiResult replay = updateTerms(docId, 0, RULES_V1, requestId);
237	        assertThat(replay.status()).isEqualTo(201);
238	        assertThat(replay.body().get("termVersion").asInt()).isEqualTo(1);
239	        assertThat(jdbc.queryForObject(
240	                "SELECT COUNT(*) FROM term_version WHERE document_id = ?", Integer.class, docId))
241	                .isEqualTo(1);
242	
243	        // 同键异参：409
244	        ApiResult conflict = updateTerms(docId, 0, "[]", requestId);
245	        assertThat(conflict.status()).isEqualTo(409);
246	
247	        // 失败不占键：先以某 requestId 触发 422（规则重复），再用同键修正参数后成功
248	        String failKey = newRequestId();
249	        ApiResult failed = updateTerms(docId, 1,
250	                "[{\"sourceTerm\":\"机器学习\",\"language\":\"en\",\"requiredTranslation\":\"ML\"},"
251	                        + "{\"sourceTerm\":\"机器学习\",\"language\":\"en\",\"requiredTranslation\":\"ml\"}]",
252	                failKey);
253	        assertThat(failed.status()).isEqualTo(422);
254	        ApiResult retried = updateTerms(docId, 1,
255	                "[{\"sourceTerm\":\"机器学习\",\"language\":\"en\",\"requiredTranslation\":\"ML\"}]", failKey);
256	        assertThat(retried.status()).isEqualTo(201);
257	        assertThat(retried.body().get("termVersion").asInt()).isEqualTo(2);
258	
259	        // 术语快照、草稿版本与去重结果原子提交：失败后未残留部分版本
260	        assertThat(jdbc.queryForObject(
261	                "SELECT COUNT(*) FROM term_version WHERE document_id = ?", Integer.class, docId))
262	                .isEqualTo(2);
263	    }
